// HasReplacedByAlias applies the HasEdge predicate on the "replaced_by_alias" edge.
func HasReplacedByAlias() predicate.SourceAlias {
	return predicate.SourceAlias(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, ReplacedByAliasTable, ReplacedByAliasColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasReplacedByAliasWith applies the HasEdge predicate on the "replaced_by_alias" edge with a given conditions (other predicates).
func HasReplacedByAliasWith(preds ...predicate.SourceAlias) predicate.SourceAlias {
	return predicate.SourceAlias(func(s *sql.Selector) {
		step := newReplacedByAliasStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasReplacedAliases applies the HasEdge predicate on the "replaced_aliases" edge.
func HasReplacedAliases() predicate.SourceAlias {
	return predicate.SourceAlias(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, true, ReplacedAliasesTable, ReplacedAliasesColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasReplacedAliasesWith applies the HasEdge predicate on the "replaced_aliases" edge with a given conditions (other predicates).
func HasReplacedAliasesWith(preds ...predicate.SourceAlias) predicate.SourceAlias {
	return predicate.SourceAlias(func(s *sql.Selector) {
		step := newReplacedAliasesStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.SourceAlias) predicate.SourceAlias {
	return predicate.SourceAlias(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.SourceAlias) predicate.SourceAlias {
	return predicate.SourceAlias(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.SourceAlias) predicate.SourceAlias {
	return predicate.SourceAlias(sql.NotPredicates(p))
}
